-- Fase 12: taxonomia (verticais e subcategorias do fornecedor), atributos de filtro, facetas e busca por sinônimos. Aditiva e idempotente.

create table if not exists public.loja_verticais (id text primary key, nome text not null, descricao text, ordem integer not null);
create table if not exists public.loja_taxonomia (categoria_slug text primary key, vertical_id text not null references public.loja_verticais(id), ordem integer not null default 0);
create table if not exists public.loja_subcategorias (id serial primary key, categoria_slug text not null, nome_menu text not null, nome_norm text not null, nome text, slug text, ordem integer not null default 0, unique (categoria_slug, nome_norm));
create table if not exists public.loja_facetas_def (faceta text not null, valor text not null, rotulo text not null, ordem integer not null default 0, primary key (faceta, valor));
create table if not exists public.loja_sinonimos (id serial primary key, padrao text not null unique, faceta text not null, valor text not null);
alter table public.loja_verticais enable row level security; alter table public.loja_taxonomia enable row level security;
alter table public.loja_subcategorias enable row level security; alter table public.loja_facetas_def enable row level security; alter table public.loja_sinonimos enable row level security;
revoke all on public.loja_verticais, public.loja_taxonomia, public.loja_subcategorias, public.loja_facetas_def, public.loja_sinonimos from anon, authenticated;

create or replace function private.loja_norm(p text) returns text language sql immutable set search_path = '' as $$
  select translate(replace(private.slugify(p), '-', ''), '0', 'o');
$$;

on conflict (id) do update set nome = excluded.nome, descricao = excluded.descricao, ordem = excluded.ordem;

on conflict (categoria_slug) do update set vertical_id = excluded.vertical_id, ordem = excluded.ordem;

